#!/usr/bin/env bash
# matrix_generator.sh — generate a GitHub Actions strategy.matrix JSON
# from a configuration file describing OS options, language versions,
# and feature flags.
set -euo pipefail

config_file="${1:?usage: matrix_generator.sh <config.json>}"

# Expand the cartesian product of os x versions into an include list.
jq -c '
  {
    "fail-fast": true,
    "matrix": {
      "include": [ .os[] as $o | .versions[] as $v | {os: $o, version: $v} ]
    }
  }
' "$config_file"

